for mid,text in rows:
 k=int(re.search(r'request (\d+)',text).group(1)); a=re.search(rf'Demo pair {k} input \(13x14\):\n((?:[0-9 ]+\n){{13}})',text).group(1); b=re.search(rf'Demo pair {k} output \(13x14\):\n((?:[0-9 ]+\n){{13}})',text).group(1)
