 print(scope, [len(x) for x in sets] if scope=='each demo' else len(sets[0]))
 if scope=='each demo': print([s[:5] for s in sets[1:]])

# Verify per-row multiset preservation and print value sums & per-position transition counts
for k,ins,outs in data:
 print('demo',k,'all multiset preserved?',all(sorted(x)==sorted(y) for x,y in zip(ins,outs)))
 print('changes',sum(x[j]!=y[j] for x,y in zip(ins,outs) for j in range(5)),'/',30)

